import fcntl,os,json; results=[]
for p in (".git/ris-agent3-scheduled.lock",".git/hmbc-coordinator.lock"):
 with open(p,"a+") as f:
  try: fcntl.flock(f,fcntl.LOCK_EX|fcntl.LOCK_NB)
  except BlockingIOError: results.append(dict(path=p,concurrentAcquisitionRefused=True,inode=os.fstat(f.fileno()).st_ino))
  else: raise SystemExit("current run lock not held: "+p)
print(json.dumps(results,indent=2))
